def execute(event):
    d = (event or {}).get("_dataset") or {}
    dataset_id = str(d.get("dataset_id") or "")
    if not dataset_id:
        return {
            "error": (
                "No dataset is bound to this tool. Wire a dataset node to "
                "the agent in the flow, or bind a dataset in the tool's "
                "properties, then try again."
            )
        }
    try:
        import pandas as pd
    except Exception:
        return {
            "error": (
                "pandas is unavailable in this runtime. Ask the operator "
                "to include it in the tool runtime image."
            )
        }
    rows = []
    page = 1
    while len(rows) < 5000:
        resp = howlet.request(
            "GET",
            "/api/v1/data-hub/datasets/" + dataset_id + "/rows",
            params={"page": page, "page_size": 500},
        )
        items = (((resp or {}).get("data") or {}).get("items")) or []
        rows.extend(
            r.get("content", r) if isinstance(r, dict) else r for r in items
        )
        if len(items) < 500:
            break
        page += 1
    df = pd.DataFrame(rows)
    if df.empty:
        return {"columns": [], "rows": [], "row_count": 0, "source_rows": 0}
    source_rows = int(len(df))
    flt = str((event or {}).get("filter") or "").strip()
    if flt:
        try:
            df = df.query(flt)
        except Exception as exc:
            return {
                "error": "filter could not be applied: %s" % exc,
                "hint": (
                    "use pandas query syntax, e.g. "
                    "price > 100 and country == 'TR'"
                ),
            }
    cols = [c for c in ((event or {}).get("columns") or []) if c in df.columns]
    if cols:
        df = df[cols]
    group_by = [
        g for g in ((event or {}).get("group_by") or []) if g in df.columns
    ]
    aggs = (event or {}).get("aggregations") or {}
    if group_by and aggs:
        try:
            df = df.groupby(group_by, dropna=False).agg(aggs).reset_index()
            df.columns = [
                "_".join(str(p) for p in c if str(p)) if isinstance(c, tuple)
                else str(c)
                for c in df.columns
            ]
        except Exception as exc:
            return {
                "error": "aggregation failed: %s" % exc,
                "hint": (
                    "aggregations maps column -> function, e.g. "
                    '{"price": "mean", "id": "count"}'
                ),
            }
    sort_by = str((event or {}).get("sort_by") or "").strip()
    if sort_by and sort_by in df.columns:
        df = df.sort_values(
            sort_by,
            ascending=str((event or {}).get("sort_dir") or "asc") != "desc",
        )
    limit = int((event or {}).get("limit") or 50)
    limit = max(1, min(limit, 200))
    out = df.head(limit)
    return {
        "columns": [str(c) for c in out.columns],
        "rows": out.to_dict(orient="records"),
        "row_count": int(len(df)),
        "returned_rows": int(len(out)),
        "source_rows": source_rows,
    }
